def props_rows(week):
    f = 'data/processed/bet_lines.csv'
    if not os.path.exists(f): return []
    out = []
    for r in csv.DictReader(open(f, encoding='utf-8')):
        try:
            if int(float(r['week'])) != int(week): continue
        except Exception: continue
        num = lambda k: (float(r[k]) if r.get(k) not in (None, '', 'nan') else None)
        out.append(dict(player=r['player'], team=r['team'], opp=r.get('opp', ''), slot=r.get('slot', ''), market=r['market'], book=r['book'], line=num('line'), over_price=num('over_price'), under_price=num('under_price'), p_over_model=num('p_over_model')))
    return out

