    eng = open('scripts/sim_engine.js', encoding='utf-8').read()
    J = dict(params=P, sims=S, bt=BT, engine=eng, props=props_rows(S['week']), team={k: dict(n=v[0], s=v[1], c=v[2]) for k, v in TEAM.items()})
    built = datetime.now().strftime('%Y-%m-%d %H:%M'); L = P['league']
    wk = S['week']; n = S['n']
    log = open('scripts/sim_model_log.html', encoding='utf-8').read() if os.path.exists('scripts/sim_model_log.html') else ''
